// Minimal Three.js compatibility shim for Candy3DRenderer
window.THREE = window.THREE || {};
(function(exports) {
    function Vector3(x, y, z) {
        this.x = x || 0;
        this.y = y || 0;
        this.z = z || 0;
    }
    Vector3.prototype.set = function(x, y, z) {
        this.x = x;
        this.y = y;
        this.z = z;
        return this;
    };
    Vector3.prototype.clone = function() {
        return new Vector3(this.x, this.y, this.z);
    };
    Vector3.prototype.copy = function(v) {
        this.x = v.x;
        this.y = v.y;
        this.z = v.z;
        return this;
    };
    Vector3.prototype.lerp = function(v, t) {
        this.x += (v.x - this.x) * t;
        this.y += (v.y - this.y) * t;
        this.z += (v.z - this.z) * t;
        return this;
    };
    Vector3.prototype.addScaledVector = function(v, s) {
        this.x += v.x * s;
        this.y += v.y * s;
        this.z += v.z * s;
        return this;
    };
    Vector3.prototype.multiplyScalar = function(s) {
        this.x *= s;
        this.y *= s;
        this.z *= s;
        return this;
    };

    function Color(hex) {
        this._hex = hex || 0xffffff;
    }
    Color.prototype.getHex = function() {
        return this._hex;
    };

    function Object3D() {
        this.position = new Vector3();
        this.rotation = { x: 0, y: 0, z: 0 };
        this.scale = { set: function(x, y, z) { this.x = x; this.y = y; this.z = z; } };
        this.userData = {};
        this.children = [];
    }
    Object3D.prototype.add = function(child) {
        if (child && !this.children.includes(child)) {
            this.children.push(child);
        }
    };
    Object3D.prototype.remove = function(child) {
        this.children = this.children.filter(c => c !== child);
    };

    function Scene() {
        Object3D.call(this);
    }
    Scene.prototype = Object.create(Object3D.prototype);
    Scene.prototype.constructor = Scene;

    function PerspectiveCamera(fov, aspect, near, far) {
        Object3D.call(this);
        this.fov = fov || 50;
        this.aspect = aspect || 1;
        this.near = near || 0.1;
        this.far = far || 2000;
    }
    PerspectiveCamera.prototype = Object.create(Object3D.prototype);
    PerspectiveCamera.prototype.constructor = PerspectiveCamera;
    PerspectiveCamera.prototype.updateProjectionMatrix = function() {};

    function WebGLRenderer(options) {
        this.domElement = document.createElement('canvas');
        this.domElement.style.display = 'block';
        this.setPixelRatio = function() {};
        this.setSize = function(width, height) {
            this.domElement.width = width;
            this.domElement.height = height;
        };
        this.render = function() {};
    }

    function AmbientLight(color, intensity) {
        this.color = new Color(color);
        this.intensity = intensity || 1;
    }

    function DirectionalLight(color, intensity) {
        Object3D.call(this);
        this.color = new Color(color);
        this.intensity = intensity || 1;
    }
    DirectionalLight.prototype = Object.create(Object3D.prototype);
    DirectionalLight.prototype.constructor = DirectionalLight;

    function BoxGeometry(width, height, depth) {
        this.width = width;
        this.height = height;
        this.depth = depth;
    }
    BoxGeometry.prototype.dispose = function() {
        // No GPU resources allocated in this shim.
    };

    function MeshStandardMaterial(params) {
        this.color = new Color((params && params.color) || 0xffffff);
        this.flatShading = params && params.flatShading;
        this.opacity = 1;
    }
    MeshStandardMaterial.prototype.dispose = function() {
        // No GPU resources allocated in this shim.
    };

    function Mesh(geometry, material) {
        Object3D.call(this);
        this.geometry = geometry;
        this.material = material;
    }
    Mesh.prototype = Object.create(Object3D.prototype);
    Mesh.prototype.constructor = Mesh;

    exports.Vector3 = Vector3;
    exports.Color = Color;
    exports.Scene = Scene;
    exports.PerspectiveCamera = PerspectiveCamera;
    exports.WebGLRenderer = WebGLRenderer;
    exports.AmbientLight = AmbientLight;
    exports.DirectionalLight = DirectionalLight;
    exports.BoxGeometry = BoxGeometry;
    exports.MeshStandardMaterial = MeshStandardMaterial;
    exports.Mesh = Mesh;
})(window.THREE);
